window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ed5aabe81b2a844c"]={"versions": [{"id": "FIG-ed5aabe81b2a844c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifests (Deployment & Execution Management). Das Modell definiert die metamodellbasierte Lokalisierung von ausführbaren Binärdateien (<code>Executable</code>), die über Prozesse (<code>Process</code>) einem übergeordneten Software-Cluster (<code>SoftwareCluster</code>) zugeordnet sind, mittels strukturierter Ablageorte (<code>ArtifactLocator</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten, Hierarchien und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> (abstrakt, erbt von <code>MultilanguageReferrable</code>): Basisklasse für identifizierbare Modellelemente mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.</li>\n<li><strong><code>PackageableElement</code></strong> (abstrakt, erbt von <code>CollectableElement</code> und <code>Identifiable</code>): Basiselement für paketierbare AUTOSAR-Elemente.</li>\n<li><strong><code>ARElement</code></strong> (abstrakt, erbt von <code>PackageableElement</code>): Oberklasse für eigenständige Modellelemente im AUTOSAR-Paket.</li>\n<li><strong><code>SoftwareCluster</code></strong> (erbt von <code>ARElement</code>): Repräsentiert eine funktionale Software-Bereitstellungseinheit mit den Attributen <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.</li>\n<li><strong><code>ArtifactLocator</code></strong> (erbt von <code>Identifiable</code>): Lokalisierungsdeskriptor für physische Artefakte mit dem Attribut <code>uri: String</code> (Multiplizität 1). Besitzt eine gerichtete Referenz <code>+representedModelElement</code> (Multiplizität <code>0..1</code>) auf ein <code>Identifiable</code>.</li>\n<li><strong><code>AbstractExecutionContext</code></strong> (abstrakt): Oberklasse für Ausführungskontexte.</li>\n<li><strong><code>Process</code></strong> (erbt von <code>AbstractExecutionContext</code>): Repräsentiert die instanziierte Ausführungseinheit auf Betriebssystemebene.</li>\n<li><strong><code>AtpClassifier</code></strong> (abstrakt, erbt von <code>ARElement</code>): Typisierende Metaklasse.</li>\n<li><strong><code>Executable</code></strong> (erbt von <code>AtpClassifier</code>): Repräsentiert das lauffähige Software-Artefakt.</li>\n</ul>\n<p class=\"fig-p\"><strong>Beziehungen & Multiplizitäten:</strong></p>\n<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> aggregiert per Komposition (<code><em>--</code>) über die Rolle <code>+artifactLocator</code> beliebig viele Instanzen von <code>ArtifactLocator</code> (<code>0..</em></code>).</li>\n<li><code>SoftwareCluster</code> referenziert über die Assoziation <code>+containedProcess</code> mehrere Instanzen von <code>Process</code> (<code>0..*</code>).</li>\n<li><code>Process</code> referenziert über die Assoziation <code>+executable</code> mit Stereotyp <code>«atpUriDef»</code> Instanzen von <code>Executable</code> (<code>0..*</code>).</li>\n<li><code>ArtifactLocator</code> referenziert über <code>+representedModelElement</code> (<code>0..1</code>) die referenzierte Zielentität (im gezeigten Szenario das <code>Executable</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet eine statische Modellierungsstruktur ab. Zur Laufzeit bzw. im Deployment- und Installationsprozess gilt folgende Auflösungsreihenfolge:</p>\n<ol class=\"fig-list\">\n<li>Ein <code>SoftwareCluster</code> bündelt logische Prozesse (<code>containedProcess</code>).</li>\n<li>Jeder <code>Process</code> verweist auf die zugrundeliegende binäre Repräsentation <code>Executable</code> (<code>executable</code>).</li>\n<li>Zur physischen Lokalisierung der Binärdatei auf dem Ziel-Dateisystem enthält der <code>SoftwareCluster</code> dedizierte <code>ArtifactLocator</code>-Instanzen.</li>\n<li>Über die Referenz <code>representedModelElement</code> verweist ein <code>ArtifactLocator</code> direkt auf das jeweilige <code>Executable</code> und stellt über <code>uri</code> den genauen Ablagepfad bereit.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Attribut <code>ArtifactLocator.uri</code> ist als obligatorisch (<code>1</code>) definiert, wodurch jeder konfigurierte Locator zwingend einen eindeutigen Pfad bzw. URI-String aufweisen muss.</li>\n<li>Das referenzierte Modellelement <code>representedModelElement</code> ist typisiert auf <code>Identifiable</code> (hier konkretisiert auf <code>Executable</code>), wodurch Artefakt-Pfade modellbasiert und typsicher verknüpft werden.</li>\n<li>Die Beziehung zwischen <code>Process</code> und <code>Executable</code> trägt das Stereotyp <code>«atpUriDef»</code>, was eine deklarative Pfad- und Namensauflösung im Kontext von AUTOSAR-Paketen kennzeichnet.</li>\n</ul>"}, {"id": "FIG-ee1c6ccdbf8fc383", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifests (Deployment & Execution Management). Das Modell definiert die metamodellbasierte Lokalisierung von ausführbaren Binärdateien (<code>Executable</code>), die über Prozesse (<code>Process</code>) einem übergeordneten Software-Cluster (<code>SoftwareCluster</code>) zugeordnet sind, mittels strukturierter Ablageorte (<code>ArtifactLocator</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten, Hierarchien und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> (abstrakt, erbt von <code>MultilanguageReferrable</code>): Basisklasse für identifizierbare Modellelemente mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.</li>\n<li><strong><code>PackageableElement</code></strong> (abstrakt, erbt von <code>CollectableElement</code> und <code>Identifiable</code>): Basiselement für paketierbare AUTOSAR-Elemente.</li>\n<li><strong><code>ARElement</code></strong> (abstrakt, erbt von <code>PackageableElement</code>): Oberklasse für eigenständige Modellelemente im AUTOSAR-Paket.</li>\n<li><strong><code>UploadableDeploymentElement</code></strong> (abstrakt): Basisklasse für verteilbare Deployment-Artefakte.</li>\n<li><strong><code>SoftwareCluster</code></strong> (erbt von <code>ARElement</code> und <code>UploadableDeploymentElement</code>): Repräsentiert eine funktionale Software-Bereitstellungseinheit mit den Attributen <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code>, <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.</li>\n<li><strong><code>ArtifactLocator</code></strong> (erbt von <code>Identifiable</code>): Lokalisierungsdeskriptor für physische Artefakte mit dem Attribut <code>uri: String [0..1]</code>. Besitzt eine gerichtete Referenz <code>+representedModelElement</code> (Multiplizität <code>0..1</code>) auf ein <code>Identifiable</code>.</li>\n<li><strong><code>AbstractExecutionContext</code></strong> (abstrakt): Oberklasse für Ausführungskontexte.</li>\n<li><strong><code>Process</code></strong> (erbt von <code>AbstractExecutionContext</code>): Repräsentiert die instanziierte Ausführungseinheit auf Betriebssystemebene.</li>\n<li><strong><code>AtpClassifier</code></strong> (abstrakt, erbt von <code>ARElement</code>): Typisierende Metaklasse.</li>\n<li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Basisklasse für Design-Elemente, die hochgeladen bzw. bereitgestellt werden können.</li>\n<li><strong><code>Executable</code></strong> (erbt von <code>AtpClassifier</code> und <code>UploadableDesignElement</code>): Repräsentiert das lauffähige Software-Artefakt.</li>\n</ul>\n<p class=\"fig-p\"><strong>Beziehungen & Multiplizitäten:</strong></p>\n<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> aggregiert per Komposition (<code><em>--</code>) über die Rolle <code>+artifactLocator</code> beliebig viele Instanzen von <code>ArtifactLocator</code> (<code>0..</em></code>).</li>\n<li><code>SoftwareCluster</code> referenziert über die Assoziation <code>+containedProcess</code> mehrere Instanzen von <code>Process</code> (<code>0..*</code>).</li>\n<li><code>Process</code> referenziert über die Assoziation <code>+executable</code> mit Stereotyp <code>«atpUriDef»</code> Instanzen von <code>Executable</code> (<code>0..*</code>).</li>\n<li><code>ArtifactLocator</code> referenziert über <code>+representedModelElement</code> (<code>0..1</code>) das zugeordnete <code>Identifiable</code> (im gezeigten Kontext das <code>Executable</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet eine statische Modellierungsstruktur ab. Zur Laufzeit bzw. im Deployment- und Installationsprozess gilt folgende Auflösungsreihenfolge:</p>\n<ol class=\"fig-list\">\n<li>Ein <code>SoftwareCluster</code> bündelt logische Prozesse (<code>containedProcess</code>).</li>\n<li>Jeder <code>Process</code> verweist auf die zugrundeliegende binäre Repräsentation <code>Executable</code> (<code>executable</code>).</li>\n<li>Zur physischen Lokalisierung der Binärdatei auf dem Ziel-Dateisystem enthält der <code>SoftwareCluster</code> dedizierte <code>ArtifactLocator</code>-Instanzen.</li>\n<li>Über die Referenz <code>representedModelElement</code> verweist ein <code>ArtifactLocator</code> direkt auf das jeweilige <code>Executable</code> und stellt über <code>uri</code> den genauen Ablagepfad bereit.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Attribut <code>ArtifactLocator.uri</code> besitzt die optionale Multiplizität <code>[0..1]</code>, wodurch ein Locator auch ohne explizite Pfadangabe existieren kann (z. B. wenn der Ablageort implizit abgeleitet wird).</li>\n<li>Durch die Vererbung von <code>UploadableDeploymentElement</code> (<code>SoftwareCluster</code>) und <code>UploadableDesignElement</code> (<code>Executable</code>) sind beide Konzepte in den standardisierten UCM-Bereitstellungsmechanismus integriert.</li>\n<li>Die Referenz <code>representedModelElement</code> bindet das <code>Executable</code> als <code>Identifiable</code> modellbasiert an den Locator, während <code>Process.executable</code> unter <code>«atpUriDef»</code> geführt wird.</li>\n</ul>"}, {"id": "FIG-1221af0f3dfe5963", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Manifests (Deployment & Execution Management). Das Modell definiert die metamodellbasierte Lokalisierung von ausführbaren Binärdateien (<code>Executable</code>), die über Prozesse (<code>Process</code>) einem übergeordneten Software-Cluster (<code>SoftwareCluster</code>) zugeordnet sind, mittels strukturierter Ablageorte (<code>ArtifactLocator</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten, Hierarchien und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> (abstrakt, erbt von <code>MultilanguageReferrable</code>): Basisklasse für identifizierbare Modellelemente mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.</li>\n<li><strong><code>PackageableElement</code></strong> (abstrakt, erbt von <code>CollectableElement</code> und <code>Identifiable</code>): Basiselement für paketierbare AUTOSAR-Elemente.</li>\n<li><strong><code>ARElement</code></strong> (abstrakt, erbt von <code>PackageableElement</code>): Oberklasse für eigenständige Modellelemente im AUTOSAR-Paket.</li>\n<li><strong><code>UploadableDeploymentElement</code></strong> (abstrakt): Basisklasse für verteilbare Deployment-Artefakte.</li>\n<li><strong><code>SoftwareCluster</code></strong> (erbt von <code>ARElement</code> und <code>UploadableDeploymentElement</code>): Repräsentiert eine funktionale Software-Bereitstellungseinheit mit den verbliebenen Attributen <code>typeApproval: String [0..1]</code>, <code>vendorId: PositiveInteger [0..1]</code> und <code>version: StrongRevisionLabelString [0..1]</code>.</li>\n<li><strong><code>ArtifactLocator</code></strong> (erbt von <code>Identifiable</code>): Lokalisierungsdeskriptor für physische Artefakte mit dem Attribut <code>uri: String [0..1]</code>. Besitzt eine gerichtete Referenz <code>+representedModelElement</code> (Multiplizität <code>0..1</code>) auf ein <code>Identifiable</code>.</li>\n<li><strong><code>AbstractExecutionContext</code></strong> (abstrakt): Oberklasse für Ausführungskontexte.</li>\n<li><strong><code>Process</code></strong> (erbt von <code>AbstractExecutionContext</code>): Repräsentiert die instanziierte Ausführungseinheit auf Betriebssystemebene.</li>\n<li><strong><code>AtpClassifier</code></strong> (abstrakt, erbt von <code>ARElement</code>): Typisierende Metaklasse.</li>\n<li><strong><code>UploadableDesignElement</code></strong> (abstrakt): Basisklasse für bereitstellbare Entwurfselemente.</li>\n<li><strong><code>Executable</code></strong> (erbt von <code>AtpClassifier</code> und <code>UploadableDesignElement</code>): Repräsentiert das lauffähige Software-Artefakt.</li>\n</ul>\n<p class=\"fig-p\"><strong>Beziehungen & Multiplizitäten:</strong></p>\n<ul class=\"fig-list\">\n<li><code>SoftwareCluster</code> aggregiert per Komposition (<code><em>--</code>) über die Rolle <code>+artifactLocator</code> beliebig viele Instanzen von <code>ArtifactLocator</code> (<code>0..</em></code>).</li>\n<li><code>SoftwareCluster</code> referenziert über die Assoziation <code>+containedProcess</code> mehrere Instanzen von <code>Process</code> (<code>0..*</code>).</li>\n<li><code>Process</code> referenziert über die Assoziation <code>+executable</code> mit Stereotyp <code>«atpUriDef»</code> Instanzen von <code>Executable</code> (<code>0..*</code>).</li>\n<li><code>ArtifactLocator</code> referenziert über <code>+representedModelElement</code> (<code>0..1</code>) das zugeordnete <code>Identifiable</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet eine statische Modellierungsstruktur ab. Zur Laufzeit bzw. im Deployment- und Installationsprozess gilt folgende Auflösungsreihenfolge:</p>\n<ol class=\"fig-list\">\n<li>Ein <code>SoftwareCluster</code> bündelt logische Prozesse (<code>containedProcess</code>).</li>\n<li>Jeder <code>Process</code> verweist auf die zugrundeliegende binäre Repräsentation <code>Executable</code> (<code>executable</code>).</li>\n<li>Zur physischen Lokalisierung der Binärdatei auf dem Ziel-Dateisystem enthält der <code>SoftwareCluster</code> dedizierte <code>ArtifactLocator</code>-Instanzen.</li>\n<li>Über die Referenz <code>representedModelElement</code> verweist ein <code>ArtifactLocator</code> direkt auf das jeweilige <code>Executable</code> und stellt über <code>uri</code> den genauen Ablagepfad bereit.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Attribut <code>ArtifactLocator.uri</code> verbleibt optional mit Multiplizität <code>[0..1]</code>.</li>\n<li>Das Installationsverhalten (<code>installationBehavior</code>) ist kein Bestandteil von <code>SoftwareCluster</code> mehr, wodurch installationsspezifische Steuerungsdaten an dieser Stelle der Metamodellstruktur entfallen.</li>\n<li>Die Zuordnung von physischer Datei (<code>ArtifactLocator</code>) zu logischem Artefakt (<code>Executable</code>) und Prozesskontext (<code>Process</code>) im <code>SoftwareCluster</code> bleibt über <code>representedModelElement</code> und <code>containedProcess</code> bestehen.</li>\n</ul>"}], "trans": [{"from": "FIG-ed5aabe81b2a844c", "to": "FIG-ee1c6ccdbf8fc383", "fr": "R22-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>ArtifactLocator.uri</code>: Multiplizität von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.</li>\n<li>Klasse <code>SoftwareCluster</code>: Abstrakte Basisklasse <code>UploadableDeploymentElement</code> hinzugefügt.</li>\n<li>Klasse <code>Executable</code>: Abstrakte Basisklasse <code>UploadableDesignElement</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-ee1c6ccdbf8fc383", "to": "FIG-1221af0f3dfe5963", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>SoftwareCluster</code>: Attribut <code>installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> entfernt.</li>\n</ul>"}]};
